-- Clarify CUT's final placing and verified seventh-place play-off details
-- for the 2018 USSA Cricket A Section campaign.
-- Source: https://www.sacricketmag.com/tuks-madibaz-b-crowned-ussa-champions/

update public.competitions
set description = 'CUT Cricket competed in the USSA Cricket A Section in Stellenbosch from 3–7 December 2018 and finished seventh. In the seventh-place play-off on 7 December, CUT defeated the University of Cape Town by 104 runs: CUT scored 180 and dismissed UCT for 76. CUT bowlers Nealan van Heerden (3/10), Jason Raubenheimer (3/21) and Devon du Plessis (3/24) each took three wickets. The accessible contemporary report does not provide CUT’s full earlier match scorecards, batting figures or further individual statistics, so these are not asserted. Source: https://www.sacricketmag.com/tuks-madibaz-b-crowned-ussa-champions/'
where id = 'a43e3a9b-7c4e-4d7e-9f7c-2018c5a00001';
